from __future__ import annotations

import json
import os
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
SKILL_DIR = ROOT / ".agents" / "skills" / "skill-eval"
REQUIRED_PATHS = (
    "SKILL.md",
    "references/evaluation-contract.md",
    "scripts/skill_eval.py",
    "scripts/skill_eval_runtime/common.py",
    "scripts/skill_eval_runtime/skill_eval.py",
)
REQUIRED_TEXT = (
    "Generated by scripts/generate_p0_runtimes.py",
    "agent-skill-eval/v1",
    "baseline and treatment",
    "positive, negative, and confusable",
    "deterministic verifier",
    "shell=False",
    "changed paths",
    "relative token",
    "EXIT_GATE = 30",
    "verifier modified the workspace",
    "repository_snapshot_digest",
    "validate-result",
    "outside the isolated fixture",
    "PYTHONDONTWRITEBYTECODE",
)
FORBIDDEN_TEXT = (
    "an llm self-report is correctness evidence",
    "lower cost offsets failed correctness",
    "shell=true",
)


class PrivateSkillEvalContractTest(unittest.TestCase):
    def test_private_payload_preserves_evaluation_contract(self) -> None:
        missing = [relative for relative in REQUIRED_PATHS if not (SKILL_DIR / relative).is_file()]
        self.assertEqual([], missing)
        text = "\n".join(
            (SKILL_DIR / relative).read_text(encoding="utf-8") for relative in REQUIRED_PATHS
        )
        lowered = text.lower()
        absent = [fixture for fixture in REQUIRED_TEXT if fixture.lower() not in lowered]
        unsafe = [fixture for fixture in FORBIDDEN_TEXT if fixture in lowered]
        self.assertEqual([], absent)
        self.assertEqual([], unsafe)

    def test_private_skill_is_absent_from_catalog_surfaces(self) -> None:
        self.assertFalse((ROOT / "skills" / "skill-eval").exists())
        skill_text = (SKILL_DIR / "SKILL.md").read_text(encoding="utf-8")
        self.assertIn("internal: true", skill_text)
        manifest = json.loads(
            (ROOT / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8")
        )
        self.assertNotIn("./skills/skill-eval", manifest["skills"])
        readme = (ROOT / "README.md").read_text(encoding="utf-8")
        self.assertNotIn("(skills/skill-eval/)", readme)

    def test_claude_projection_targets_private_source(self) -> None:
        projection = ROOT / ".claude" / "skills" / "skill-eval"
        self.assertTrue(projection.is_symlink())
        target = os.readlink(str(projection)).replace("\\", "/")
        self.assertEqual("../../.agents/skills/skill-eval", target)


if __name__ == "__main__":
    unittest.main()
